<template><section class="page"><h2>我的账户</h2><template v-if="!logged"><van-cell-group inset><van-field v-model="phone" label="手机号" placeholder="11 位手机号"/><van-field v-model="password" label="密码" type="password"/><van-field v-model="nickName" label="昵称（注册时必填）"/></van-cell-group><div class="bar"><van-button type="primary" @click="login">登录</van-button><van-button plain @click="register">注册</van-button></div></template><template v-else><div class="card"><b>{{ profile?.nickName }}</b><p class="note">{{ profile?.phone }}</p><van-button size="small" @click="logout">退出登录</van-button></div><h3>收货地址</h3><div v-for="a in addresses" :key="a.id" class="card">{{ a.receiverName }} · {{ a.receiverPhone }}<br>{{ a.province }}{{ a.city }}{{ a.district }}{{ a.detailAddress }}</div><van-cell-group inset><van-field v-model="address.receiverName" label="收货人"/><van-field v-model="address.receiverPhone" label="联系电话"/><van-field v-model="address.province" label="省份"/><van-field v-model="address.city" label="城市"/><van-field v-model="address.district" label="区县"/><van-field v-model="address.detailAddress" label="详细地址"/></van-cell-group><van-button block type="primary" @click="addAddress">添加地址</van-button><h3>收藏与足迹</h3><div class="card">已收藏 {{ favorites.length }} 件 · 最近浏览 {{ history.length }} 件</div></template></section></template>
<script setup>
import{reactive,ref,onMounted}from'vue';import{showToast}from'vant';import{memberApi}from'../api'
const phone=ref(''),password=ref(''),nickName=ref(''),logged=ref(!!localStorage.getItem('member-token')),profile=ref(null),addresses=ref([]),favorites=ref([]),history=ref([]),address=reactive({receiverName:'',receiverPhone:'',province:'',city:'',district:'',detailAddress:''})
async function load(){if(!logged.value)return;try{profile.value=(await memberApi.profile()).data;addresses.value=(await memberApi.addresses()).data||[];favorites.value=(await memberApi.favorites()).data.records||[];history.value=(await memberApi.browseHistory()).data.records||[]}catch(e){showToast(e)}}async function login(){try{const r=await memberApi.login({phone:phone.value,password:password.value});localStorage.setItem('member-token',r.data.token);logged.value=true;load()}catch(e){showToast(e)}}async function register(){try{await memberApi.register({phone:phone.value,password:password.value,nickName:nickName.value});showToast('注册成功，请登录')}catch(e){showToast(e)}}async function addAddress(){try{await memberApi.addAddress(address);showToast('地址已添加');Object.keys(address).forEach(k=>address[k]='');load()}catch(e){showToast(e)}}function logout(){localStorage.removeItem('member-token');logged.value=false}onMounted(load)
</script>
